PNG

# every LocalSend launcher on this computer: apt or source, Flatpak (system and yours), Snap
found=""
for d in $(printf '%s' "${XDG_DATA_DIRS:-/usr/local/share:/usr/share}" | tr ':' ' ') \
         /usr/local/share /usr/share /var/lib/flatpak/exports/share "$DATA/flatpak/exports/share" \
         /var/lib/snapd/desktop "$HOME/.local/share"; do
    for src in "$d"/applications/*localsend*.desktop "$d"/applications/*LocalSend*.desktop; do
        [ -f "$src" ] || continue
        base=$(basename "$src")
        dest="$APPS/$base"
        [ "$src" = "$dest" ] && continue
        case " $found " in *" $base "*) continue ;; esac   # the first one found wins, as in the menu
        found="$found $base"
        # a launcher you made yourself under that name is kept for --undo
        if [ -f "$dest" ] && ! grep -q "^$MARK" "$dest"; then cp "$dest" "$KEEP/apps/$base"; fi
        sed -e "s/^Icon=.*/Icon=$NAME/" -e "/^\[Desktop Entry\]/a $MARK" "$src" > "$dest.tmp"
        mv "$dest.tmp" "$dest"
    done
done

# other launchers of yours that start LocalSend with another icon
for f in "$APPS"/*.desktop; do
    [ -f "$f" ] || continue
    grep -q "^$MARK" "$f" && continue
    grep -Eqi '^Exec=.*localsend' "$f" || continue
    icon=$(sed -n 's/^Icon=//p' "$f" | head -n 1)
    [ "$icon" = "$NAME" ] && continue
    base=$(basename "$f")
    [ -f "$KEEP/apps/$base" ] || cp "$f" "$KEEP/apps/$base"
    sed "s/^Icon=.*/Icon=$NAME/" "$f" > "$f.tmp" && mv "$f.tmp" "$f"
    found="$found $base"
done
refresh

say "LocalSend now has the new icon."
[ -n "$found" ] || say "I didn't find LocalSend on this computer yet; run this again after installing it."
say "If you still see the old one, press Ctrl+Alt+Esc to refresh Cinnamon (or log out and in)."
say "To undo: curl -fsSL https://github.com/jrypzm/yrs/releases/download/mint-localsend/install-yrs-localsend.sh | sh -s -- --undo"
